from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
rw=Chem.RWMol()
# Core atom labels and indices
labels=['A','B','C','D','E','F','G','H','nL','J','K','L','M','P','Q','nR','R','S','T','ClL','ClR',
        'C1','C2','C3','C4','C5','O5','C6','O2','O3','O4','O6']
idx={n:i for i,n in enumerate(labels)}
# atom types
for name in labels:
    if name.startswith('Cl'): a=Chem.Atom('Cl')
    elif name.startswith('n'): a=Chem.Atom('N'); a.SetIsAromatic(True)
    elif name.startswith('O'): a=Chem.Atom('O')
    elif name.startswith('C'): a=Chem.Atom('C')
    else: a=Chem.Atom('C')
    if name in ['A','B','C','D','E','F','G','H','J','K','L','M','P','Q','R','S','T']:
        a.SetIsAromatic(True)
    if name=='nL':
        a.SetNumExplicitHs(1); a.SetNoImplicit(True)
    if name=='nR': a.SetNoImplicit(True)
    rw.AddAtom(a)
# aromatic ring edges
rings=[['A','B','C','D','E','F'], ['C','G','H','nL','D'], ['G','J','K','L','M','H'], ['L','P','Q','nR','M'], ['P','T','S','R','Q']]
for ring in rings:
    for u,v in zip(ring,ring[1:]+ring[:1]):
        rw.AddBond(idx[u],idx[v],Chem.BondType.AROMATIC)
# exocyclic/core bonds
for u,v in [('A','ClL'),('T','ClR'),('nR','C1'),
            ('C1','C2'),('C2','C3'),('C3','C4'),('C4','C5'),('C5','O5'),('O5','C1'),
            ('C5','C6'),('C2','O2'),('C3','O3'),('C4','O4'),('C6','O6')]:
    rw.AddBond(idx[u],idx[v],Chem.BondType.SINGLE)
m=rw.GetMol()
Chem.SanitizeMol(m)
# Set desired absolute configurations per wedges.
for name in ['C2','C3','C4']:
    m.GetAtomWithIdx(idx[name]).SetChiralTag(Chem.ChiralType.CHI_TETRAHEDRAL_CCW)
Chem.AssignStereochemistry(m, cleanIt=True, force=True)
target={'C2':'R','C3':'S','C4':'R'}
for name,code in target.items():
    a=m.GetAtomWithIdx(idx[name])
    got=a.GetProp('_CIPCode') if a.HasProp('_CIPCode') else None
    print(name, 'initial',got)
    if got!=code:
        a.SetChiralTag(Chem.ChiralType.CHI_TETRAHEDRAL_CW if a.GetChiralTag()==Chem.ChiralType.CHI_TETRAHEDRAL_CCW else Chem.ChiralType.CHI_TETRAHEDRAL_CCW)
Chem.AssignStereochemistry(m, cleanIt=True, force=True)
print('SMILES', Chem.MolToSmiles(m))
for n in ['C2','C3','C4']:
    a=m.GetAtomWithIdx(idx[n]);print(n,a.GetProp('_CIPCode'))
m=Chem.AddHs(m)
params=AllChem.ETKDGv3();params.randomSeed=190146;params.numThreads=1
res=AllChem.EmbedMolecule(m,params)
print('embed',res,'atoms',m.GetNumAtoms())
if res<0: raise RuntimeError('embed failed')
props=AllChem.MMFFGetMoleculeProperties(m)
if props is None: raise RuntimeError('No MMFF')
print('mmff',AllChem.MMFFOptimizeMolecule(m,mmffVariant='MMFF94s',maxIters=1000))
Chem.AssignStereochemistry(m, cleanIt=True, force=True)
print('final stereo',[(n,m.GetAtomWithIdx(idx[n]).GetProp('_CIPCode')) for n in ['C2','C3','C4']])
conf=m.GetConformer()
with open('answer.xyz','w') as f:
    f.write(f'{m.GetNumAtoms()}\n')
    f.write('Generated structure for mol_0146\n')
    for i,a in enumerate(m.GetAtoms()):
        x,y,z=conf.GetAtomPosition(i)
        f.write(f'{a.GetSymbol():2s} {x: .8f} {y: .8f} {z: .8f}\n')
